"""A miniature but structurally complete dataset, for the training-bench tests.

Three sessions so `tasks.py split` can produce a train/val/test partition at all, and every
class in every session so no fold is missing one — which `src/dataset.py` refuses, correctly,
since a class with no training images cannot be learned.

**The class list is the fixture's own, not `config/classes.json`.** That file is generated by
F1 from a real mode sweep and the live path is deliberately empty until then
(`docs/annexes/f3a-dry-run/README.md`). A test suite that only passes while a particular
`config/classes.json` happens to be checked in is a test suite that will break on the day F1
lands, for no reason connected to what it is testing.

Built with the same renderer `tools/synth_capture.py` uses, so what these tests train on is
the same kind of image the dry run produces.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import cv2
import numpy as np

REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO_ROOT / "tools"))

from synth_capture import render_frame

from calibrate import calibrate, write_calibration
from ingest import ingest_session
from metadata import session_date
from split import split_dataset

#: Six classes with one (n, m) mode shape each, so they are at least visually distinguishable.
#: The frequencies are the F3a dry run's, kept only so a failure reads familiarly.
CLASSES = [
    {"index": 0, "freq_hz": 420, "shape": (1, 2)},
    {"index": 1, "freq_hz": 610, "shape": (1, 3)},
    {"index": 2, "freq_hz": 860, "shape": (2, 3)},
    {"index": 3, "freq_hz": 1170, "shape": (1, 4)},
    {"index": 4, "freq_hz": 1540, "shape": (2, 4)},
    {"index": 5, "freq_hz": 1970, "shape": (3, 4)},
]

SESSION_IDS = ("SYNTH-20260101-01", "SYNTH-20260102-01", "SYNTH-20260103-01")


def class_list() -> list[dict]:
    """The list in the shape `config/classes.json` stores it — index and frequency only."""
    return [{"index": c["index"], "freq_hz": c["freq_hz"]} for c in CLASSES]


def write_classes_json(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(
            {
                "version": "1.0.0",
                "provenance": "synthetic",
                "n_classes": len(CLASSES),
                "classes": class_list(),
            },
            indent=2,
        ),
        encoding="utf-8",
    )
    return path


def build_dataset(root: Path, frames_per_class: int = 3) -> Path:
    """Write, ingest and split a complete miniature dataset under `root`.

    Leaves `<root>/classes.json` beside it, so a test that needs to build a model for this
    dataset has the same frozen list ingest was driven by.
    """
    rng = np.random.default_rng(11)
    write_classes_json(root / "classes.json")

    for session_id in SESSION_IDS:
        session_dir = root / "raw" / session_id
        good = None
        for entry in CLASSES:
            freq_dir = session_dir / str(entry["freq_hz"])
            freq_dir.mkdir(parents=True, exist_ok=True)
            n, m = entry["shape"]
            for k in range(frames_per_class):
                frame = render_frame(n, m, rng, "lamp_diffuse", n_markers=4)
                good = good if good is not None else frame
                cv2.imwrite(
                    str(freq_dir / f"IMG_{k:04d}.png"),
                    cv2.cvtColor(frame, cv2.COLOR_RGBA2BGRA),
                )

        (session_dir / "session.json").write_text(
            json.dumps(
                {
                    "session_id": session_id,
                    "date": session_date(session_id),
                    "operator": "test",
                    "plate": "test-200x200",
                    "synthetic": True,
                    "material": "sand",
                    "grain_mass_g": 2.0,
                    "distance_mm": 210,
                    "lighting": "lamp_diffuse",
                    "dwell_s": 3.0,
                    "notes": "",
                }
            ),
            encoding="utf-8",
        )
        write_calibration(calibrate(good, session_id=session_id), root / "calib")
        ingest_session(session_id, root)

    split_dataset(root)
    return root
